WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What are the three states of matter?', 'Solid, liquid and gas.', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Describe the arrangement and movement of particles in a solid.', 'Closely packed in a regular arrangement, vibrating about fixed positions.', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Describe the arrangement and movement of particles in a liquid.', 'Close together but randomly arranged, able to move past each other.', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Describe the arrangement and movement of particles in a gas.', 'Far apart and randomly arranged, moving quickly in all directions.', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the name for the change from liquid to gas at the boiling point?', 'Boiling (evaporation also happens at the surface below the boiling point).', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the name for the change directly from solid to gas?', 'Sublimation.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the name for the change from gas to liquid?', 'Condensation.', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the name for the change from liquid to solid?', 'Freezing.', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What happens to the particles when a solid melts?', 'They gain energy, vibrate more and overcome enough of the forces between them to move past each other.', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the difference between a physical change and a chemical change?', 'A physical change (e.g. change of state) forms no new substance and is easily reversed; a chemical change forms new substances.', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'In a physical change, what happens to the particles themselves?', 'They stay the same; only their arrangement, movement and energy change.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is one limitation of the particle model that shows particles as solid spheres?', 'It ignores the forces between particles, the space inside particles and the fact that particles are not solid or inelastic.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Who proposed that atoms are tiny solid spheres that cannot be divided?', 'John Dalton.', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What was Thomson''s model of the atom?', 'The plum pudding model: a ball of positive charge with electrons embedded in it.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What did Geiger and Marsden''s alpha-scattering experiment show?', 'Most alpha particles passed straight through gold foil, but a few were deflected, showing a tiny, dense, positive nucleus.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Whose model replaced the plum pudding model after the alpha-scattering experiment?', 'Rutherford''s nuclear model.', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What did Bohr add to the model of the atom?', 'Electrons orbit the nucleus in fixed energy levels (shells).', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Why has the model of the atom changed over time?', 'New experimental evidence could not be explained by the old model.', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Describe the structure of an atom.', 'A small, positively charged nucleus of protons and neutrons, surrounded by negatively charged electrons in shells.', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'How does the radius of the nucleus compare with the radius of the atom?', 'The nucleus is much smaller, about 1/100 000 of the atom''s radius.', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Where is most of the mass of an atom?', 'In the nucleus.', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What is the typical order of magnitude of the radius of an atom?', 'About 10⁻¹⁰ m.', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What are the relative charges of a proton, a neutron and an electron?', 'Proton +1, neutron 0, electron −1.', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What are the relative masses of a proton, a neutron and an electron?', 'Proton 1, neutron 1, electron about 1/2000 (negligible).', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'Why is an atom neutral overall?', 'It has the same number of protons as electrons.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What does the atomic number tell you?', 'The number of protons in the nucleus.', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What does the mass number tell you?', 'The total number of protons and neutrons in the nucleus.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'How many protons, neutrons and electrons are in an atom of ³⁵Cl (atomic number 17)?', '17 protons, 18 neutrons, 17 electrons.', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'What are isotopes?', 'Atoms of the same element with the same number of protons but different numbers of neutrons.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C1', 'Particles', 'How many electrons are in a Mg²⁺ ion (atomic number 12)?', '10 — the atom has lost 2 electrons.', 30),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What does ''pure'' mean in chemistry?', 'A single element or compound, not mixed with any other substance.', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How does the everyday meaning of ''pure'' differ from the scientific one?', 'In everyday use it means natural or with nothing added (e.g. pure orange juice), even though it is a mixture.', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How can melting point be used to test purity?', 'A pure substance melts at a sharp, fixed temperature; an impure one melts over a range, usually lower.', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is a formulation?', 'A mixture designed as a useful product, with each component in a measured quantity, e.g. an alloy, paint or medicine.', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How is relative formula mass (Mr) calculated?', 'Add up the relative atomic masses (Ar) of all the atoms in the formula.', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is the Mr of CO₂? (C = 12, O = 16)', '12 + 16 + 16 = 44.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is an empirical formula?', 'The simplest whole-number ratio of atoms of each element in a compound.', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is the empirical formula of C₆H₁₂O₆?', 'CH₂O.', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Which technique separates an insoluble solid from a liquid?', 'Filtration.', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How do you obtain crystals of a soluble salt from its solution?', 'Heat to evaporate some of the water, leave to cool so crystals form, then filter and dry them (crystallisation).', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Which technique separates a solvent from a solution, e.g. water from salty water?', 'Simple distillation.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'When is fractional distillation used?', 'To separate a mixture of liquids with similar boiling points, e.g. ethanol and water or crude oil.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What are the two phases in chromatography?', 'A stationary phase (paper or TLC plate) and a mobile phase (the solvent).', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What does separation in chromatography depend on?', 'How each substance distributes between the stationary and mobile phases.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is the formula for an Rf value?', 'Rf = distance moved by spot ÷ distance moved by solvent front.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How does a chromatogram show a pure substance?', 'It gives a single spot in every solvent.', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Why is the start line in paper chromatography drawn in pencil?', 'Pencil is insoluble, so it will not run with the solvent.', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How are ions formed?', 'Atoms lose or gain electrons — metals lose electrons to form positive ions, non-metals gain electrons to form negative ions.', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is an ionic bond?', 'The strong electrostatic attraction between oppositely charged ions.', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is a covalent bond?', 'A shared pair of electrons between two non-metal atoms.', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is metallic bonding?', 'The attraction between positive metal ions and a sea of delocalised electrons.', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is the electronic structure of sodium (atomic number 11)?', '2.8.1', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How does the group number relate to electronic structure?', 'The group number equals the number of electrons in the outer shell (for Groups 1–7).', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How did Mendeleev arrange the elements, and how was this refined?', 'By atomic mass, leaving gaps for undiscovered elements; the modern table is arranged by atomic number.', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Why does diamond have a very high melting point and not conduct electricity?', 'Each carbon forms four strong covalent bonds in a giant structure, and there are no free electrons.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Why does graphite conduct electricity?', 'Each carbon forms three bonds, leaving one delocalised electron per atom that can move between the layers.', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'What is graphene?', 'A single layer of graphite: one atom thick, strong and a good conductor.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Why do simple molecular substances have low melting and boiling points?', 'Only weak intermolecular forces need to be overcome, not the covalent bonds.', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'Why do ionic compounds conduct electricity when molten or dissolved but not when solid?', 'The ions are free to move when molten or dissolved; in a solid they are held in fixed positions.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C2', 'Elements, Compounds and Mixtures', 'How big are nanoparticles?', 'Between 1 nm and 100 nm across (a few hundred atoms or fewer).', 30),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the formula of sulfuric acid?', 'H₂SO₄', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the formula of the ammonium ion?', 'NH₄⁺', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the formula of calcium hydroxide?', 'Ca(OH)₂', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What do the state symbols (s), (l), (g) and (aq) mean?', 'Solid, liquid, gas, and aqueous (dissolved in water).', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the law of conservation of mass?', 'No atoms are made or lost in a reaction, so the total mass of products equals the total mass of reactants.', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'Why might mass appear to decrease when a reaction is done in an open flask?', 'A gas product escapes into the air.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is a mole?', 'The amount of substance containing 6.02 × 10²³ particles (the Avogadro constant).', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the equation linking mass, moles and Mr?', 'Amount (mol) = mass (g) ÷ Mr.', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'How many moles are in 9 g of water? (Mr = 18)', '9 ÷ 18 = 0.5 mol.', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is a limiting reactant?', 'The reactant that is completely used up, so it limits the amount of product formed.', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is an exothermic reaction?', 'A reaction that transfers energy to the surroundings, so the temperature of the surroundings rises.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is an endothermic reaction?', 'A reaction that takes in energy from the surroundings, so the temperature of the surroundings falls.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is activation energy?', 'The minimum energy needed for a reaction to occur.', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'On a reaction profile for an exothermic reaction, where are the products?', 'Lower in energy than the reactants.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'Is bond breaking exothermic or endothermic?', 'Endothermic — energy is taken in to break bonds.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'How is the overall energy change found from bond energies?', 'Energy taken in to break bonds − energy released making bonds (negative = exothermic).', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is oxidation in terms of oxygen?', 'Gain of oxygen.', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is oxidation in terms of electrons?', 'Loss of electrons (OIL RIG: Oxidation Is Loss, Reduction Is Gain).', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What ions do acids produce in water?', 'Hydrogen ions, H⁺(aq).', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What ions do alkalis produce in water?', 'Hydroxide ions, OH⁻(aq).', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the ionic equation for neutralisation?', 'H⁺(aq) + OH⁻(aq) → H₂O(l)', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What are the products when a metal carbonate reacts with an acid?', 'A salt, water and carbon dioxide.', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What are the products when a metal reacts with an acid?', 'A salt and hydrogen.', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the difference between a strong acid and a weak acid?', 'A strong acid is fully ionised in water; a weak acid is only partially ionised.', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What is the difference between a dilute acid and a concentrated acid?', 'A dilute acid has a small amount of acid per unit volume; a concentrated acid has a large amount.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'If H⁺ concentration increases by a factor of 10, what happens to the pH?', 'It decreases by 1.', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'How can pH be measured?', 'With universal indicator (compare the colour with a chart) or a pH meter/probe.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'In electrolysis with inert electrodes, where are metals or hydrogen formed?', 'At the cathode (negative electrode).', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What are the products of electrolysis of molten sodium chloride?', 'Sodium at the cathode and chlorine at the anode.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C3', 'Chemical Reactions', 'What are the products of electrolysis of aqueous copper sulfate with inert electrodes?', 'Copper at the cathode and oxygen at the anode.', 30),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the trend in reactivity down Group 1?', 'Reactivity increases.', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Why does Group 1 reactivity increase down the group?', 'The outer electron is further from the nucleus and more shielded, so it is lost more easily.', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What forms when sodium reacts with water?', 'Sodium hydroxide and hydrogen: 2Na + 2H₂O → 2NaOH + H₂', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the trend in reactivity down Group 7?', 'Reactivity decreases.', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Why does Group 7 reactivity decrease down the group?', 'The outer shell is further from the nucleus, so an extra electron is gained less easily.', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the trend in melting and boiling points down Group 7?', 'They increase.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the state and colour of chlorine at room temperature?', 'A pale green gas.', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the state and colour of bromine at room temperature?', 'A red-brown liquid.', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is a displacement reaction of halogens?', 'A more reactive halogen displaces a less reactive halide from solution, e.g. Cl₂ + 2KBr → 2KCl + Br₂.', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is seen when chlorine water is added to potassium iodide solution?', 'The solution turns brown as iodine forms.', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Why are the noble gases unreactive?', 'They have a full outer shell of electrons.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the trend in boiling point down Group 0?', 'Boiling point increases.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Give three typical properties of transition metals compared with Group 1 metals.', 'Higher melting points, higher densities, less reactive (also form coloured compounds and ions with different charges).', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Why are transition metals useful in industry?', 'They and their compounds are often good catalysts, e.g. iron in the Haber process.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'How is the reactivity of a metal related to the ions it forms?', 'The more easily a metal forms its positive ion, the more reactive it is.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'How can an order of reactivity of metals be found experimentally?', 'Compare their reactions with water or dilute acid, or use displacement reactions with metal salt solutions.', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is seen when magnesium is added to copper sulfate solution?', 'A brown coating of copper forms and the blue colour fades — magnesium displaces copper.', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for hydrogen?', 'A lit splint gives a squeaky pop.', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for oxygen?', 'It relights a glowing splint.', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for carbon dioxide?', 'It turns limewater milky (cloudy).', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for chlorine?', 'It bleaches damp litmus paper white.', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What colour precipitate does Cu²⁺ form with sodium hydroxide solution?', 'Blue.', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What colour precipitates do Fe²⁺ and Fe³⁺ form with sodium hydroxide solution?', 'Fe²⁺ gives green; Fe³⁺ gives orange-brown.', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'Which two cations give a white precipitate with sodium hydroxide, and how are they told apart?', 'Ca²⁺ and Zn²⁺; the zinc hydroxide precipitate dissolves in excess sodium hydroxide, calcium hydroxide does not.', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for carbonate ions?', 'Add dilute acid — it fizzes and the gas turns limewater milky.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What colours do chloride, bromide and iodide give with acidified silver nitrate?', 'Chloride white, bromide cream, iodide yellow precipitate.', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What is the test for sulfate ions?', 'Add acidified barium chloride (or barium nitrate) — a white precipitate forms.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What are the flame test colours for Li⁺, Na⁺, K⁺, Ca²⁺ and Cu²⁺?', 'Li⁺ crimson, Na⁺ yellow, K⁺ lilac, Ca²⁺ orange-red, Cu²⁺ green.', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'How is a flame test carried out?', 'Dip a clean nichrome wire loop in the sample and hold it in a hot (blue) Bunsen flame.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C4', 'Predicting and Identifying Reactions and Products', 'What are the advantages of instrumental methods of analysis?', 'They are more sensitive, more accurate and faster.', 30),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is the unit of concentration in moles?', 'mol/dm³', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'How is concentration in mol/dm³ calculated?', 'Concentration = amount (mol) ÷ volume (dm³).', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'How do you convert cm³ to dm³?', 'Divide by 1000.', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is the concentration of 0.2 mol of solute in 500 cm³ of solution?', '0.2 ÷ 0.5 = 0.4 mol/dm³.', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Which apparatus measures out exactly 25.0 cm³ of alkali for a titration?', 'A volumetric pipette (with a pipette filler).', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is the end point of a titration?', 'The point at which the indicator changes colour, showing the acid and alkali have exactly reacted.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What are concordant titres?', 'Titres within 0.10 cm³ of each other; these are used to calculate the mean.', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Why is the conical flask swirled during a titration?', 'To mix the reactants so the indicator colour change is seen at the right moment.', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What volume does 1 mole of any gas occupy at room temperature and pressure?', '24 dm³', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What volume does 0.25 mol of oxygen occupy at RTP?', '0.25 × 24 = 6 dm³.', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is percentage yield?', '(Actual mass of product ÷ theoretical mass) × 100.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Give two reasons why the actual yield is less than the theoretical yield.', 'The reaction may be reversible, product is lost when separating it, or side reactions occur.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is atom economy?', '(Mr of desired product ÷ total Mr of all reactants) × 100.', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Why is a high atom economy desirable?', 'Less waste is produced, so the process is more sustainable and often cheaper.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Name three ways to follow the rate of a reaction.', 'Measure gas volume over time, mass loss over time, or time for a colour change or precipitate to appear.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What does the gradient of a volume of gas–time graph show?', 'The rate of reaction.', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'In the disappearing cross experiment, how is rate related to the time taken?', 'Rate is proportional to 1/time.', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is the effect of increasing temperature on rate, and why?', 'The rate increases — particles move faster, so they collide more often and more collisions have energy ≥ the activation energy.', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Why does increasing concentration increase the rate?', 'There are more particles in the same volume, so collisions are more frequent.', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Why does increasing the pressure of a gas increase the rate?', 'Particles are closer together, so collisions are more frequent.', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Why does powder react faster than lumps of the same mass?', 'It has a larger surface area to volume ratio, so there are more frequent collisions.', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is a catalyst?', 'A substance that speeds up a reaction without being used up.', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'How does a catalyst increase the rate?', 'It provides an alternative reaction pathway with a lower activation energy.', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What are enzymes?', 'Biological catalysts.', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'Which black powder catalyses the decomposition of hydrogen peroxide?', 'Manganese(IV) oxide, MnO₂.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is a reversible reaction?', 'A reaction in which the products can react to re-form the reactants (shown by ⇌).', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What is dynamic equilibrium?', 'In a closed system, the forward and reverse reactions happen at the same rate, so concentrations stay constant.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What happens to the equilibrium position if the temperature is increased?', 'It shifts in the endothermic direction.', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What happens to the equilibrium position if the pressure is increased?', 'It shifts towards the side with fewer moles of gas.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C5', 'Monitoring and Controlling Chemical Reactions', 'What happens to the equilibrium position if the concentration of a reactant is increased?', 'It shifts to the right, making more product.', 30),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'How are metals less reactive than carbon extracted from their ores?', 'By reduction with carbon, e.g. heating the oxide with carbon (coke).', 1),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Why is aluminium extracted by electrolysis rather than with carbon?', 'Aluminium is more reactive than carbon, so carbon cannot reduce its oxide.', 2),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Why is aluminium oxide dissolved in molten cryolite for electrolysis?', 'It lowers the operating temperature, saving energy.', 3),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What are phytoextraction and bioleaching?', 'Biological metal extraction: plants absorb metal compounds and are burned to ash; bacteria produce leachate solutions containing metal compounds.', 4),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the equation for the Haber process?', 'N₂ + 3H₂ ⇌ 2NH₃', 5),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What conditions are used in the Haber process?', 'About 450 °C, 200 atmospheres and an iron catalyst.', 6),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Why is a compromise temperature used in the Haber process?', 'A lower temperature gives a higher yield but too slow a rate; 450 °C gives a reasonable yield quickly.', 7),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Which three elements do fertilisers mainly supply?', 'Nitrogen, phosphorus and potassium (NPK).', 8),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is a life-cycle assessment?', 'An assessment of the environmental impact of a product at each stage: raw materials, manufacture, use and disposal.', 9),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the composition of brass?', 'Copper and zinc.', 10),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the composition of bronze?', 'Copper and tin.', 11),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What two substances are needed for iron to rust?', 'Oxygen and water.', 12),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'How does sacrificial protection prevent rusting?', 'A more reactive metal (e.g. zinc) is attached and corrodes instead of the iron.', 13),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is galvanising?', 'Coating iron or steel with zinc, which acts as a barrier and gives sacrificial protection.', 14),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is a homologous series?', 'A family of compounds with the same functional group and general formula, differing by CH₂.', 15),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the general formula of the alkanes?', 'CₙH₂ₙ₊₂', 16),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the functional group of the alkenes?', 'The C=C double bond.', 17),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the test for an alkene?', 'Bromine water turns from orange to colourless.', 18),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the functional group of the alcohols?', '–OH', 19),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the functional group of the carboxylic acids?', '–COOH', 20),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is addition polymerisation?', 'Many small alkene monomers join together to form a long polymer chain, with no other product.', 21),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the difference between addition and condensation polymerisation?', 'Condensation polymerisation joins monomers with two functional groups and releases a small molecule such as water.', 22),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Name three naturally occurring polymers.', 'DNA (from nucleotides), proteins (from amino acids) and starch or cellulose (from sugars).', 23),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'How is crude oil separated into fractions?', 'Fractional distillation: it is vaporised and the fractions condense at different heights in a column, depending on their boiling points.', 24),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Why do larger hydrocarbon molecules have higher boiling points?', 'They have stronger intermolecular forces, which need more energy to overcome.', 25),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is cracking?', 'Breaking long-chain alkanes into shorter, more useful alkanes and alkenes, using a catalyst and high temperature.', 26),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'What is the only product of a hydrogen–oxygen fuel cell?', 'Water.', 27),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'How did the early atmosphere become rich in oxygen?', 'Photosynthesis by algae and plants removed carbon dioxide and released oxygen.', 28),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'How do greenhouse gases warm the Earth?', 'They absorb infrared radiation emitted from the Earth''s surface and re-emit it, warming the atmosphere.', 29),
  ('Chemistry', 'OCR A', 'gcse', 'C6', 'Global Challenges', 'Name a source and an effect of sulfur dioxide pollution.', 'Burning fuels containing sulfur impurities; it causes acid rain.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Chemistry' AND exam_board = 'OCR A' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

-- Flashcard top-up: Chemistry|OCR B|gcse — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/chemistry-ocr-b-gcse.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What does the particle model say about solids, liquids and gases?', 'Solids: particles touching in a fixed, regular arrangement, vibrating. Liquids: particles touching but randomly arranged and able to move past each other. Gases: particles far apart, moving quickly in random directions.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is the difference between a physical change and a chemical change?', 'A physical change (e.g. a change of state) makes no new substance and is easily reversed; a chemical change makes new substances.', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Why do different substances melt and boil at different temperatures?', 'The stronger the forces between the particles, the more energy must be transferred to overcome them, so the higher the melting or boiling point.', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Do individual particles have the same properties as the bulk substance?', 'No — e.g. a single particle of copper is not coloured or hot or cold; bulk properties come from many particles together.', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Give a limitation of the particle model when particles are drawn as inelastic spheres.', 'It does not show the scale, real shape or movement of particles, ignores the forces between them and assumes the particles bounce without energy loss.', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What were the main gases in the Earth''s early atmosphere and where did they come from?', 'Mainly carbon dioxide and water vapour (with some nitrogen and small amounts of other gases), released by intense volcanic activity.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How did the oceans form?', 'As the Earth cooled, water vapour condensed to form the oceans.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How did oxygen build up in the atmosphere?', 'Photosynthesising organisms (algae, then plants) took in carbon dioxide and released oxygen.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How did the amount of carbon dioxide in the atmosphere fall?', 'It was taken in by photosynthesis, dissolved in the oceans, and locked up in sedimentary rocks (e.g. limestone), fossil fuels such as oil and gas.', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What evidence is used to work out how the atmosphere has changed?', 'The types and chemical composition of ancient rocks and fossil evidence of early life.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is the approximate composition of today''s dry air?', 'About 78% nitrogen, 21% oxygen, about 1% argon and about 0.04% carbon dioxide.', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What causes carbon monoxide and particulates to form from fuels?', 'Incomplete combustion — burning a fuel in a limited supply of oxygen.', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How is sulfur dioxide produced when fuels burn?', 'Sulfur impurities in the fuel react with oxygen.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How are oxides of nitrogen formed in engines?', 'At high temperatures nitrogen from the air is oxidised; nitrogen monoxide is then further oxidised in the air.', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What harm do sulfur dioxide and oxides of nitrogen cause?', 'They cause acid rain and breathing problems; nitrogen oxides also help form photochemical smog.', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Why is carbon monoxide dangerous?', 'It is toxic — it reduces the blood''s ability to carry oxygen.', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Name three ways of decreasing pollutant emissions from fuels.', 'Catalytic converters, low-sulfur petrol and gas scrubbers (e.g. in power station chimneys).', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is oxidation in terms of oxygen?', 'Gain of oxygen — so combustion of a fuel is an oxidation reaction.', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Describe the tests for oxygen, hydrogen and carbon dioxide.', 'Oxygen relights a glowing splint; hydrogen burns with a squeaky pop with a lighted splint; carbon dioxide turns limewater milky (cloudy).', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is an exothermic reaction?', 'A reaction that transfers energy to the surroundings, so the temperature of the surroundings increases (e.g. combustion).', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is an endothermic reaction?', 'A reaction that takes in energy from the surroundings, so the temperature of the surroundings decreases.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is activation energy?', 'The minimum energy needed to break bonds so that a reaction can start.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'On a reaction profile for an exothermic reaction, where are the products?', 'Lower in energy than the reactants; the difference is the energy given out.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Is bond breaking exothermic or endothermic?', 'Bond breaking takes in energy (endothermic); bond making gives out energy (exothermic).', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How do you calculate the energy change from bond energies?', 'Energy change = energy taken in to break bonds − energy given out making bonds. A negative answer means the reaction is exothermic.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'How does a hydrogen–oxygen fuel cell compare with burning hydrogen?', 'It uses the same overall reaction and makes only water, but transfers the energy electrically to drive a motor rather than in an engine.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What is the greenhouse effect?', 'The warm Earth emits infrared radiation; greenhouse gases such as carbon dioxide and methane absorb it and re-emit it in all directions, keeping the Earth warmer than it would otherwise be.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'What evidence links human activity to climate change?', 'A correlation between rising atmospheric CO₂ concentration, fossil fuel consumption and global temperatures over the last 200 years.', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Give four possible effects of increased CO₂ and methane on the climate.', 'Changes to where crops can be grown, more extreme weather, melting polar ice and flooding of low-lying land.', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C1', 'Air and Water', 'Describe how potable water is produced and how chlorine is tested for.', 'Ground/waste water is filtered (including membrane filtration), aerated, treated with bacteria and chlorinated; salt water can be distilled. Chlorine turns damp blue litmus paper red and then bleaches it white.', 30),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What was Dalton''s model of the atom?', 'Atoms are tiny, solid, indivisible spheres; each element has its own type of atom.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What was Thomson''s ''plum pudding'' model?', 'A ball of positive charge with negative electrons embedded in it, after he discovered the electron.', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What did Rutherford''s experiment show?', 'Most of the atom is empty space, with a tiny, dense, positively charged nucleus at the centre that contains most of the mass.', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What did Bohr add to the atomic model?', 'Electrons orbit the nucleus in fixed shells (energy levels).', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Give the relative charges and masses of protons, neutrons and electrons.', 'Proton +1, mass 1; neutron 0, mass 1; electron −1, mass about 1/2000 (very small).', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is the typical size of an atom?', 'About 10⁻¹⁰ m across; the nucleus is about 100 000 times smaller than the atom.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'How do you work out the numbers of protons, neutrons and electrons in an atom?', 'Protons = atomic number; electrons = protons (in a neutral atom); neutrons = mass number − atomic number.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What are isotopes?', 'Atoms of the same element with the same number of protons but different numbers of neutrons.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is the electron arrangement of sodium (atomic number 11)?', '2.8.1', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'How is the position of an element in the Periodic Table linked to its electrons?', 'The group number equals the number of outer-shell electrons; the period number equals the number of occupied shells.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'How did Mendeleev arrange the elements?', 'By relative atomic mass and by their properties, putting similar elements in groups.', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Why did Mendeleev leave gaps and swap some elements?', 'So elements lined up with others with similar properties; he predicted that the gaps were undiscovered elements and predicted their properties.', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What later evidence supported Mendeleev''s table?', 'Newly discovered elements (e.g. germanium) fitted his gaps and properties, and ordering by atomic number (proton number) explained his reorderings.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Compare the typical physical properties of metals and non-metals.', 'Metals: shiny, high melting points, dense, good electrical conductors. Non-metals: dull, often low melting points, low density, poor conductors (except graphite).', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What are the Group 1 metals like?', 'Soft metals with low density that are stored under oil; they tarnish quickly in moist air and react vigorously with water and chlorine.', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is the trend in reactivity of Group 1 and why?', 'Reactivity increases down the group because the outer electron is further from the nucleus and more easily lost.', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is produced when a Group 1 metal reacts with water?', 'A metal hydroxide (an alkaline solution) and hydrogen, e.g. 2Na + 2H₂O → 2NaOH + H₂.', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Give the states and colours of chlorine, bromine and iodine at room temperature.', 'Chlorine: pale green gas. Bromine: red-brown liquid (orange-brown vapour). Iodine: grey-black solid (purple vapour).', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is the trend in reactivity of Group 7 and why?', 'Reactivity decreases down the group because the outer shell is further from the nucleus, so it is harder to gain an electron.', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What is a halogen displacement reaction?', 'A more reactive halogen displaces a less reactive halogen from a solution of its metal halide, e.g. chlorine + potassium bromide → potassium chloride + bromine.', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Why are the Group 0 elements unreactive?', 'Their atoms have a full outer shell of electrons, so they do not need to gain, lose or share electrons; they exist as single atoms.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What properties do the Group 0 elements have?', 'Colourless gases at room temperature with very low melting and boiling points.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'How does ionic bonding form?', 'A metal atom transfers electron(s) to a non-metal atom, forming a positive and a negative ion with full outer shells, which attract strongly.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What charge do Group 1 and Group 7 ions have?', 'Group 1 ions are 1+ (lose one electron); Group 7 ions are 1− (gain one electron).', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Describe the structure of an ionic compound.', 'A giant lattice of positive and negative ions held together by strong electrostatic attractions in all directions.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Why do ionic compounds have high melting points?', 'A lot of energy is needed to overcome the strong electrostatic attraction between oppositely charged ions.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'When do ionic compounds conduct electricity?', 'When molten or dissolved in water, because the ions can move; not when solid, because the ions are fixed.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'Give a limitation of dot-and-cross diagrams of ionic compounds.', 'They do not show the 3-D arrangement, relative sizes of ions, or that the ions form a giant lattice.', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What do the state symbols (s), (l), (g) and (aq) mean?', 'Solid, liquid, gas and aqueous (dissolved in water).', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C2', 'Chemical Patterns', 'What are the general properties of transition metals?', 'High melting points and densities, less reactive than Group 1, form coloured ions with different charges (e.g. Fe²⁺, Fe³⁺) and are used as catalysts.', 30),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Describe metallic bonding.', 'A giant lattice of positive metal ions surrounded by a ''sea'' of delocalised electrons; strong electrostatic attraction holds the structure together.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why are metals malleable and ductile?', 'The layers of ions can slide over each other while still being held together by the delocalised electrons.', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why do metals conduct electricity and heat?', 'The delocalised electrons are free to move through the structure.', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why do metals have high melting points?', 'There is strong electrostatic attraction between the positive ions and the delocalised electrons, which takes a lot of energy to overcome.', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'How can metals be placed in a reactivity series?', 'By comparing their reactions with water and dilute acid and their displacement reactions with compounds of other metals.', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Give the reactivity series from potassium to silver.', 'Potassium, sodium, calcium, magnesium, aluminium, (carbon), zinc, iron, lead, (hydrogen), copper, silver.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why are some metals more reactive than others?', 'More reactive metals lose electrons to form positive ions more easily.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is a metal displacement reaction?', 'A more reactive metal displaces a less reactive metal from a compound, e.g. zinc + copper sulfate → zinc sulfate + copper.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Write the ionic equation for zinc displacing copper from copper sulfate solution.', 'Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s)', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Which metals can be extracted by heating with carbon?', 'Metals below carbon in the reactivity series, e.g. zinc, iron, lead and copper.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'In extraction with carbon, what is oxidised and what is reduced?', 'The metal oxide is reduced (loses oxygen) and carbon is oxidised (gains oxygen).', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why are some metals extracted by electrolysis?', 'They are more reactive than carbon, so carbon cannot reduce their oxides (e.g. aluminium).', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What are bacterial extraction and phytoextraction?', 'Biological methods that use bacteria or plants to extract metals (e.g. copper) from low-grade ores or waste; they save energy and new ore but are slow.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is electrolysis?', 'The decomposition of an electrolyte (a molten or dissolved ionic compound) by an electric current.', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why must an ionic compound be molten or dissolved to be electrolysed?', 'So that the ions are free to move to the electrodes.', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What forms at each electrode with inert electrodes?', 'Metals (or hydrogen) form at the cathode (negative); non-metals form at the anode (positive).', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What are the products of electrolysis of molten lead bromide?', 'Lead at the cathode and bromine at the anode.', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'In electrolysis, what are oxidation and reduction in terms of electrons?', 'Oxidation is loss of electrons (at the anode); reduction is gain of electrons (at the cathode). OIL RIG.', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Write the half equation at the cathode in aluminium extraction.', 'Al³⁺ + 3e⁻ → Al', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why must the carbon anodes be replaced in aluminium extraction?', 'Oxygen formed at the anode reacts with the hot carbon to form carbon dioxide, so the anodes burn away.', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'In the electrolysis of an aqueous salt, when does hydrogen form at the cathode?', 'When the metal is more reactive than hydrogen (e.g. sodium); less reactive metals such as copper or silver are deposited instead.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What forms at the anode in electrolysis of aqueous solutions?', 'Oxygen usually forms (from hydroxide ions from water), but a concentrated chloride solution gives chlorine.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What are the products of electrolysis of concentrated sodium chloride solution?', 'Hydrogen at the cathode and chlorine at the anode; sodium hydroxide is left in solution.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is crude oil and why is it important?', 'A finite mixture of hydrocarbons; it is the main source of fuels and a feedstock for the petrochemical industry (including polymers).', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'How does fractional distillation separate crude oil?', 'Crude oil is vaporised; the column is hot at the bottom and cool at the top, so fractions condense at different heights according to their boiling points.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why do larger hydrocarbon molecules have higher boiling points?', 'They have stronger intermolecular forces, so more energy is needed to separate the molecules.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is the general formula of the alkanes?', 'CₙH₂ₙ₊₂ — e.g. methane CH₄, ethane C₂H₆, propane C₃H₈, butane C₄H₁₀.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is a covalent bond?', 'A strong bond formed when two atoms share a pair of electrons.', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'Why do simple molecular substances have low melting and boiling points?', 'Only the weak intermolecular forces between molecules need to be overcome; the covalent bonds do not break.', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C3', 'Chemicals of the Natural Environment', 'What is cracking and why is it done?', 'Breaking long-chain alkanes into shorter, more useful alkanes (e.g. for petrol) and alkenes, which are used to make polymers; it matches supply to demand.', 30),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Name the main classes of material compared in C4.', 'Glass and clay ceramics, polymers, composites and metals.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is a composite material?', 'A material made of two or more materials combined to give useful properties, e.g. reinforced concrete (steel rods in concrete).', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why are ceramics used for plates and insulators?', 'They are hard, stiff, have high melting points and are electrical insulators, though brittle.', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is an alloy?', 'A mixture of a metal with other elements (usually other metals or carbon).', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why are alloys harder than pure metals?', 'Atoms of different sizes disrupt the regular layers, so the layers cannot slide over each other as easily.', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is steel?', 'An alloy of iron with carbon (and sometimes other metals, e.g. chromium in stainless steel), stronger and harder than iron.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is addition polymerisation?', 'Many small alkene monomers join together when their C=C double bonds open, forming one long chain with no other product.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is the repeating unit of poly(ethene)?', '–CH₂–CH₂– (shown in brackets with ''n''), made from ethene monomers CH₂=CH₂.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is condensation polymerisation?', 'Monomers with two functional groups each join together, and a small molecule (usually water) is released at each link.', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What do polyesters and polyamides form from?', 'Polyesters: dicarboxylic acids and diols. Polyamides: dicarboxylic acids and diamines.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Name three naturally occurring polymers and their monomers.', 'DNA (four nucleotides), proteins (amino acids) and starch/cellulose (sugars).', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why does carbon form so many compounds?', 'Each carbon atom can form four covalent bonds and carbon atoms can bond to each other in chains and rings.', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why do long polymer chains have higher melting points than small molecules?', 'Longer chains have more intermolecular forces between them, which need more energy to overcome.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is the structure of diamond?', 'A giant covalent structure in which each carbon atom is bonded to four others in a rigid 3-D lattice.', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why is diamond very hard with a very high melting point?', 'Many strong covalent bonds must be broken.', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What is the structure of graphite?', 'Layers of hexagonal rings in which each carbon atom bonds to three others, with weak forces between the layers and one delocalised electron per atom.', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why is graphite soft and slippery and why does it conduct?', 'The layers slide over each other easily; the delocalised electrons can move through the structure.', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What are allotropes?', 'Different structural forms of the same element, e.g. diamond, graphite, graphene and fullerenes.', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Do giant covalent substances conduct electricity?', 'Usually not (e.g. diamond), because there are no free electrons or ions — graphite and graphene are exceptions.', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What size are nanoparticles?', '1–100 nm (1 nm = 10⁻⁹ m) — similar in scale to molecules, containing a few hundred atoms.', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'How does surface area to volume ratio change as particle size decreases?', 'It increases — e.g. halving the side of a cube doubles its surface area to volume ratio.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why are nanoparticles good catalysts?', 'Their very high surface area to volume ratio exposes many more atoms to react.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What are fullerenes used for?', 'Hollow cages (e.g. buckyballs) can carry drug molecules into the body; nanotubes are used as molecular sieves and to strengthen materials such as sports equipment.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What are the properties of graphene?', 'A single layer of graphite one atom thick; very strong, and an excellent conductor of electricity and heat.', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What are the possible risks of nanoparticles?', 'Their tiny size lets them enter cells and tissues, and their large surface area may make them reactive or toxic; their long-term health effects are not well known.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What conditions are needed for iron to rust?', 'Both oxygen (air) and water.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'How do barrier methods prevent rusting?', 'Paint, oil, grease or plastic keep air and water away from the iron.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'How does sacrificial protection work?', 'A more reactive metal such as zinc is attached or coated; it is oxidised instead of the iron, even if the coating is scratched.', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'What stages are considered in a life-cycle assessment (LCA)?', 'Extracting and processing raw materials, manufacture, transport, use, and disposal (landfill, incineration, recycling) — including water, energy and environmental impact.', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C4', 'Material Choices', 'Why is reusing a PET bottle better than recycling it?', 'Reuse needs less energy than breaking down and reprocessing the material; recycling still saves crude oil compared with making new PET.', 30),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What is a pure substance in chemistry?', 'A single element or compound, not mixed with any other substance.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How does ''pure'' in everyday language differ from the chemical meaning?', 'Everyday ''pure'' means natural or with nothing added (e.g. ''pure orange juice''), which can still be a mixture.', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What is a formulation?', 'A mixture designed as a useful product, with components in measured proportions, e.g. paints, medicines, fertilisers.', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How can melting point show whether a substance is pure?', 'A pure substance melts at a sharp, fixed temperature that matches data values; impurities lower the melting point and make it melt over a range.', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What are the two phases in chromatography?', 'The stationary phase (e.g. paper) and the mobile phase (the solvent); substances separate by their distribution between the two.', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you calculate an Rf value?', 'Rf = distance moved by the substance ÷ distance moved by the solvent front.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How does chromatography show whether a substance is pure?', 'A pure substance gives a single spot in all solvents; a mixture gives two or more spots.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'When is a locating agent needed in chromatography?', 'When the substances are colourless, so the spots can be seen after the chromatogram has run.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'Why might a non-aqueous solvent be used in chromatography?', 'Some substances are insoluble in water, so another solvent (e.g. ethanol) is needed to move them.', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How is an insoluble solid separated from a liquid?', 'Filtration — the solid stays on the filter paper as the residue and the liquid passes through as the filtrate.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How is a soluble solid obtained from its solution as crystals?', 'Crystallisation — warm to evaporate some solvent until crystals start to form, then leave to cool and filter off the crystals.', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'When is simple distillation used?', 'To separate a solvent from a solution, e.g. pure water from salt water.', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'When is fractional distillation used?', 'To separate a mixture of miscible liquids with different boiling points, e.g. ethanol and water or crude oil.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'Why is representative sampling needed in analysis?', 'So the sample tested has the same composition as the bulk material and any variation is detected.', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'Give the flame test colours for Li⁺, Na⁺, K⁺, Ca²⁺ and Cu²⁺.', 'Lithium crimson red, sodium yellow, potassium lilac, calcium orange-red, copper green (blue-green).', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What precipitates do Cu²⁺, Fe²⁺ and Fe³⁺ give with sodium hydroxide solution?', 'Cu²⁺ blue, Fe²⁺ green, Fe³⁺ orange-brown.', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you distinguish Ca²⁺ and Zn²⁺ with sodium hydroxide?', 'Both give a white precipitate; the zinc hydroxide precipitate dissolves in excess sodium hydroxide, the calcium one does not.', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you test for carbonate ions?', 'Add dilute acid — bubbles of gas form that turn limewater milky (carbon dioxide).', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you test for chloride, bromide and iodide ions?', 'Add dilute nitric acid then silver nitrate solution: chloride gives a white precipitate, bromide cream, iodide yellow.', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you test for sulfate ions?', 'Add dilute hydrochloric acid then barium chloride solution — a white precipitate of barium sulfate forms.', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How is emission spectroscopy used to identify elements?', 'A hot sample emits light with a unique pattern of lines; matching the lines to reference spectra identifies the elements.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What are the advantages of instrumental methods of analysis?', 'They are more sensitive, faster and more accurate, and record data automatically — but are expensive.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What is the law of conservation of mass?', 'No atoms are made or lost in a reaction, so the total mass of products equals the total mass of reactants.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'Why can the mass appear to change in an open container?', 'A gas may escape (mass decreases) or a gas from the air may react with a reactant (mass increases).', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you calculate relative formula mass (Mr)?', 'Add the relative atomic masses of all the atoms in the formula, e.g. Mr of H₂O = 2 + 16 = 18.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What is the Avogadro constant?', '6.02 × 10²³ — the number of particles in one mole of a substance.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you calculate the number of moles from a mass?', 'Moles = mass (g) ÷ relative formula mass.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'What volume does one mole of any gas occupy at RTP?', '24 dm³ (moles of gas = volume in dm³ ÷ 24).', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How do you calculate concentration in mol/dm³?', 'Concentration = moles of solute ÷ volume of solution in dm³.', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C5', 'Chemical Analysis', 'How is a titration carried out for precise, accurate results?', 'Pipette a fixed volume of alkali into a flask, add indicator, add acid from a burette with swirling until the colour just changes; do a rough titre then repeat until concordant (within 0.10 cm³) and take the mean.', 30),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What are the products when an acid reacts with a metal?', 'A salt and hydrogen, e.g. magnesium + hydrochloric acid → magnesium chloride + hydrogen.', 1),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What are the products when an acid reacts with a metal carbonate?', 'A salt, water and carbon dioxide.', 2),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What are the products when an acid reacts with an alkali?', 'A salt and water (neutralisation).', 3),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Which salts do hydrochloric, nitric and sulfuric acid make?', 'Chlorides, nitrates and sulfates respectively.', 4),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is the ionic equation for neutralisation?', 'H⁺(aq) + OH⁻(aq) → H₂O(l)', 5),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How do you make a pure, dry sample of a soluble salt from an insoluble base?', 'Add excess base to warm acid, filter off the excess, heat the filtrate to evaporate some water, leave to crystallise, then filter and dry the crystals.', 6),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How is an insoluble salt made?', 'Mix two solutions that contain its ions (precipitation), filter, wash the precipitate with distilled water and dry it.', 7),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How is pH measured?', 'With universal indicator (compare the colour with a chart) or with a pH meter.', 8),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is the difference between a strong and a weak acid?', 'A strong acid is completely ionised in solution; a weak acid is only partly ionised.', 9),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is the difference between concentrated and dilute?', 'Concentration is the amount of acid per volume of solution — not the same as strength.', 10),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How does pH change if the hydrogen ion concentration increases by a factor of 10?', 'The pH decreases by 1.', 11),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Why do weak acids react more slowly than strong acids of the same concentration?', 'They have a lower concentration of H⁺ ions.', 12),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Name four factors that affect the rate of a reaction.', 'Temperature, concentration (or pressure for gases), surface area of solids, and catalysts.', 13),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How does increasing temperature increase the rate?', 'Particles move faster, so they collide more often and, more importantly, more collisions have energy greater than the activation energy.', 14),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Why does increasing concentration or pressure increase the rate?', 'There are more particles in the same volume, so collisions are more frequent.', 15),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Why does powdering a solid increase the rate?', 'Smaller pieces have a larger surface area to volume ratio, so more particles are exposed and collisions are more frequent.', 16),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is a catalyst?', 'A substance that increases the rate of a reaction but is unchanged chemically and in mass at the end.', 17),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How does a catalyst work?', 'It provides an alternative reaction pathway with a lower activation energy.', 18),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What are enzymes?', 'Proteins that act as biological catalysts, working best within a narrow range of temperature and pH.', 19),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How can the rate of a reaction that produces a gas be measured?', 'Measure the volume of gas with a gas syringe (or collection over water), or measure the loss in mass on a balance, at regular time intervals.', 20),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How can rate be measured for a reaction that forms a precipitate or changes colour?', 'Time how long it takes for a cross under the flask to disappear, or follow the colour change by eye or with a colorimeter.', 21),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How is rate found from a graph of product against time?', 'The gradient of the curve; the gradient of a tangent gives the rate at a particular time.', 22),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What does the symbol ⇌ mean?', 'The reaction is reversible — it can go in both directions.', 23),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is dynamic equilibrium?', 'In a closed system, the forward and reverse reactions happen at the same rate, so the amounts of reactants and products stay constant.', 24),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Does a catalyst change the yield of a reversible reaction?', 'No — it increases the rate of both forward and reverse reactions, so equilibrium is reached faster but the yield is unchanged.', 25),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What is the equation for the Haber process?', 'N₂(g) + 3H₂(g) ⇌ 2NH₃(g) — nitrogen from the air, hydrogen from natural gas and steam.', 26),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'What conditions are used in the Haber process?', 'About 450 °C, about 200 atmospheres and an iron catalyst; unreacted nitrogen and hydrogen are recycled.', 27),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Why is a compromise temperature used in the Haber process?', 'The forward reaction is exothermic, so a lower temperature gives a higher yield but too slow a rate; very high pressures are also expensive and risky.', 28),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'Why are fertilisers needed and what problem can they cause?', 'They replace nitrogen, phosphorus and potassium taken up by crops; overuse washes them into rivers, causing eutrophication.', 29),
  ('Chemistry', 'OCR B', 'gcse', 'C6', 'Making Useful Chemicals', 'How do you calculate atom economy?', 'Atom economy = (Mr of desired product ÷ total Mr of all reactants) × 100%; a higher atom economy is more sustainable.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Chemistry' AND exam_board = 'OCR B' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;

COMMIT;
